                  <linearGradient id="dealsBg3" x1="0" y1="0" x2="1" y2="1">
                    <stop offset="0%" stopColor="#dfe6df"/>
                    <stop offset="100%" stopColor="#a8c0b3"/>
                  </linearGradient>
                </defs>
                <rect width="600" height="600" fill="url(#dealsBg3)"/>
                <rect x="120" y="380" width="360" height="120" rx="14" fill="#1a1a1a" opacity=".1"/>
              </svg>
            </div>
            <span className="tag">Members</span>
            <h3>Free engraving on Studio ceramics</h3>
            <p>Personalise mugs, carafes and serving boards through Sunday.</p>
            <div><a className="btn btn-secondary" href="#shop-deal-3">Personalise yours</a></div>
          </article>
        </div>
      </div>
    </section>
  );
}

function Editorial() {
  return (
    <section id="editorial" aria-labelledby="editorial-title">
      <div className="container">
        <header className="section-head">
          <div>
            <span className="eyebrow">The journal</span>
            <h2 id="editorial-title">Reading, watching, making</h2>
            <p>Stories from the studios, kitchens and homes behind the things we sell.</p>
          </div>
          <a className="btn btn-ghost" href="#all-articles">All stories </a>
        </header>

        <div className="editorial-grid">
          {ARTICLES.map(a => (
            <article key={a.id} className="article">
              <div className="article-media" role="img" aria-label={`Editorial illustration for: ${a.title}`}>
                <EditorialArt palette={a.palette} />
              </div>
              <p className="meta">{a.category} · {a.read}</p>
              <h3><a href={`#article-${a.id}`}>{a.title}</a></h3>
              <p>{a.excerpt}</p>
              <a className="btn btn-ghost" href={`#article-${a.id}`} aria-label={`Read: ${a.title}`}>Read story </a>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

function Values() {
  return (
    <section className="values" aria-label="Our promises">
      <div className="container values-grid">
        {VALUES.map(v => (
          <div className="value" key={v.title}>
            <div className="icon" aria-hidden="true"><Icon name={v.icon} size={20} /></div>
            <div>
              <h3>{v.title}</h3>
              <p>{v.body}</p>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}

function Newsletter() {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState({ kind: "idle", message: "" });
  const liveId = "newsletter-status";

  const onSubmit = (e) => {
    e.preventDefault();
    const trimmed = email.trim();
    const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed);
    if (!ok) {
      setStatus({ kind: "error", message: "Please enter a valid email address." });
      return;
    }
    setStatus({ kind: "ok", message: `Thanks — we sent a confirmation to ${trimmed}.` });
    setEmail("");
  };

  return (
    <section className="newsletter" aria-labelledby="news-title">
      <div className="container">
        <div>
          <h2 id="news-title">Slow letters, not spam.</h2>
          <p>One thoughtful email each Friday: new arrivals, restocks, and reading from the journal. Unsubscribe any time.</p>
        </div>
        <form noValidate onSubmit={onSubmit} aria-describedby="news-help">
          <div className="field">
            <label htmlFor="news-email">Email address</label>
            <input
              id="news-email"
              type="email"
              autoComplete="email"
              required
              placeholder="you@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              aria-invalid={status.kind === "error" ? "true" : undefined}
              aria-describedby={`news-help ${status.kind !== "idle" ? liveId : ""}`.trim()}
            />
          </div>
          <button type="submit" className="btn btn-primary">Subscribe</button>
          <p id="news-help" className="help">We'll never share your address. <a href="#privacy" style={{ color: "inherit", textDecoration: "underline" }}>Privacy policy</a>.</p>
          <p
            id={liveId}
            role="status"
            aria-live="polite"
            className={`status${status.kind === "error" ? " error" : ""}`}
          >
            {status.message}
          </p>
        </form>
      </div>
    </section>
  );
}

function Footer() {
  const cols = [
    { title: "Shop",    links: ["New arrivals", "Bestsellers", "Apparel", "Home & living", "Kitchen", "Sale"] },
    { title: "Help",    links: ["Customer care", "Shipping & returns", "Order status", "Size guide", "Gift cards", "Contact us"] },
    { title: "Company", links: ["Our story", "Sustainability", "Makers", "Journal", "Careers", "Press"] },
  ];
  return (
    <footer className="site-footer" aria-labelledby="footer-title">
      <h2 id="footer-title" className="sr-only">Site footer</h2>
      <div className="container">
        <div>
          <a href="#top" className="brand" aria-label="Maren and Oak — home">◯ Maren &amp; Oak</a>
          <p className="tagline">Modern essentials, made to last.</p>
          <ul className="socials" aria-label="Social media">
            <li><a href="#instagram" aria-label="Maren and Oak on Instagram"><Icon name="ig" size={18} /></a></li>
            <li><a href="#twitter"   aria-label="Maren and Oak on X"><Icon name="tw" size={18} /></a></li>
            <li><a href="#youtube"   aria-label="Maren and Oak on YouTube"><Icon name="yt" size={18} /></a></li>
          </ul>
        </div>
        {cols.map(col => (
          <nav key={col.title} aria-label={col.title}>
            <h3>{col.title}</h3>
            <ul>
              {col.links.map(l => <li key={l}><a href={`#${l.toLowerCase().replace(/\W+/g, "-")}`}>{l}</a></li>)}
            </ul>
          </nav>
        ))}
      </div>
      <div className="container legal">
        <span>© {new Date().getFullYear()} Maren &amp; Oak Trading Co.</span>
        <span><a href="#privacy">Privacy</a> · <a href="#terms">Terms</a> · <a href="#accessibility">Accessibility</a></span>
      </div>
    </footer>
  );
}

/* ---------- App ---------- */

function App() {
  const [favorites, setFavorites] = useState(() => new Set());
  const [cart, setCart] = useState([]);
  const [toast, setToast] = useState("");
  const toastTimer = useRef(0);

  const toggleFavorite = useCallback((id) => {
    setFavorites(prev => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  }, []);

  const addToCart = useCallback((product) => {
    setCart(prev => [...prev, product.id]);
    setToast(`Added ${product.title} to your bag.`);
    clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(""), 3500);
  }, []);

  const onOpenCart = () => setToast(cart.length ? `You have ${cart.length} item${cart.length === 1 ? "" : "s"} in your bag.` : "Your bag is empty.");
  const onOpenSearch = () => setToast("Search is unavailable in this demo.");

  return (
    <Fragment>
      <Announcement />
      <Header cartCount={cart.length} onOpenCart={onOpenCart} onOpenSearch={onOpenSearch} />
      <main id="main" tabIndex="-1">
        <Hero onShop={() => document.getElementById("featured-title")?.scrollIntoView({ behavior: "smooth", block: "start" })} />
        <CategoriesStrip />
        <Featured favorites={favorites} onToggleFavorite={toggleFavorite} onAdd={addToCart} />
        <Deals />
        <Editorial />
        <Values />
        <Newsletter />
      </main>
      <Footer />

      {/* Global live region for cart/search status */}
      <div role="status" aria-live="polite" className="sr-only">{toast}</div>
    </Fragment>
  );
}

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(<StrictMode><App /></StrictMode>);
