/* Maren & Oak — ecommerce home page (React 18 + Babel standalone). */
const { useState, useEffect, useMemo, useCallback, useRef, StrictMode, Fragment } = React;

/* ---------- Decorative SVG illustrations (no external images) ---------- */

function HeroArt() {
  return (
    <svg viewBox="0 0 600 750" preserveAspectRatio="xMidYMid slice" aria-hidden="true" focusable="false">
      <defs>
        <linearGradient id="hg" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#e6dfcc" />
          <stop offset="100%" stopColor="#a89e83" />
