        <rect x="380" y="520" width="160" height="14" rx="3" />
        <rect x="445" y="320" width="6" height="200" />
        <ellipse cx="448" cy="320" rx="55" ry="22" />
        <path d="M393 320 Q448 230 503 320 Z" />
      </g>
      <g fill="#1a1a1a" opacity=".88">
        <path d="M80 540 Q90 360 220 360 L300 360 Q380 360 380 460 L380 540 Z" />
        <rect x="100" y="540" width="20" height="120" />
        <rect x="340" y="540" width="20" height="120" />
