      <defs>
        <linearGradient id={id} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor={a} />
          <stop offset="100%" stopColor={b} />
        </linearGradient>
      </defs>
      <rect width="400" height="500" fill={`url(#${id})`} />
      {shape === "bottle" && (
        <g fill="#1a1a1a" opacity=".82">
          <rect x="170" y="120" width="60" height="40" rx="4" />
          <path d="M150 160 Q150 180 170 195 L170 380 Q170 420 200 420 Q230 420 230 380 L230 195 Q250 180 250 160 Z" />
