          <path d="M280 220 Q330 230 330 280 Q330 330 280 340 L280 320 Q310 312 310 280 Q310 248 280 240 Z" />
        </g>
      )}
      {shape === "shirt" && (
        <g fill="#1a1a1a" opacity=".82">
          <path d="M100 180 L160 150 Q200 200 240 150 L300 180 L330 240 L280 260 L280 380 L120 380 L120 260 L70 240 Z" />
        </g>
      )}
      {shape === "bag" && (
        <g fill="#1a1a1a" opacity=".82">
