}

/* ---------- Icons ---------- */
const Icon = ({ name, size = 20 }) => {
  const common = { width: size, height: size, viewBox: "0 0 24 24", fill: "none", stroke: "currentColor", strokeWidth: 1.7, strokeLinecap: "round", strokeLinejoin: "round", "aria-hidden": true, focusable: "false" };
  switch (name) {
    case "search":  return <svg {...common}><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>;
    case "user":    return <svg {...common}><circle cx="12" cy="8" r="4"/><path d="M4 21c1.5-4 5-6 8-6s6.5 2 8 6"/></svg>;
    case "heart":   return <svg {...common}><path d="M12 21s-7-4.5-9.5-9A5.5 5.5 0 0 1 12 6a5.5 5.5 0 0 1 9.5 6c-2.5 4.5-9.5 9-9.5 9Z"/></svg>;
    case "bag":     return <svg {...common}><path d="M5 8h14l-1 12H6Z"/><path d="M9 8a3 3 0 0 1 6 0"/></svg>;
    case "menu":    return <svg {...common}><path d="M4 7h16M4 12h16M4 17h16"/></svg>;
    case "close":   return <svg {...common}><path d="M6 6l12 12M18 6 6 18"/></svg>;
    case "truck":   return <svg {...common}><path d="M3 7h11v9H3z"/><path d="M14 10h4l3 3v3h-7"/><circle cx="7" cy="18" r="2"/><circle cx="17" cy="18" r="2"/></svg>;
    case "leaf":    return <svg {...common}><path d="M5 19c0-8 6-14 14-14 0 8-6 14-14 14Z"/><path d="M5 19c4-4 8-6 14-14"/></svg>;
    case "shield":  return <svg {...common}><path d="M12 3 4 6v6c0 5 3.5 8 8 9 4.5-1 8-4 8-9V6Z"/><path d="m9 12 2 2 4-4"/></svg>;
    case "rotate":  return <svg {...common}><path d="M3 12a9 9 0 0 1 15.5-6.3L21 8"/><path d="M21 3v5h-5"/><path d="M21 12a9 9 0 0 1-15.5 6.3L3 16"/><path d="M3 21v-5h5"/></svg>;
    case "ig":      return <svg {...common}><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r="1" fill="currentColor"/></svg>;
    case "tw":      return <svg {...common}><path d="M4 4l7 9-7 7h3l5.5-5.5L17 20h3l-7.5-9.5L20 4h-3l-4.5 4.5L9 4Z"/></svg>;
    case "yt":      return <svg {...common}><rect x="3" y="6" width="18" height="12" rx="3"/><path d="m11 10 4 2-4 2Z" fill="currentColor"/></svg>;
    default:        return null;
  }
};

/* ---------- Data ---------- */
const NAV = [
  { href: "#new",       label: "New" },
  { href: "#women",     label: "Women" },
  { href: "#men",       label: "Men" },
  { href: "#home",      label: "Home" },
  { href: "#editorial", label: "Journal" },
  { href: "#sale",      label: "Sale" },
];

const CATEGORIES = ["Bestsellers", "Apparel", "Home & Living", "Kitchen", "Bath & Body", "Accessories", "Gift Cards"];

const FEATURED = [
  { id: "p1", title: "Ridge Linen Overshirt",  category: "Apparel",       price: 148, rating: 4.8, reviews: 312, badge: { type: "new",  label: "New" }, art: { shape: "shirt",  palette: ["#cdd9c8", "#7d9c84"] } },
  { id: "p2", title: "Ember Pillar Candle",    category: "Home",          price: 38,  rating: 4.9, reviews: 821, art: { shape: "candle", palette: ["#f1d9b5", "#c8911a"] } },
  { id: "p3", title: "Studio Ceramic Mug",     category: "Kitchen",       price: 28,  was: 36, rating: 4.7, reviews: 564, badge: { type: "sale", label: "Sale" }, art: { shape: "mug",    palette: ["#e7e0d2", "#9c8a6e"] } },
  { id: "p4", title: "Field Canvas Tote",      category: "Accessories",   price: 64,  rating: 4.6, reviews: 198, art: { shape: "bag",    palette: ["#dcd2bf", "#7a6a4f"] } },
  { id: "p5", title: "Daily Wash — Cedar",     category: "Bath & Body",   price: 22,  rating: 4.9, reviews: 1204, badge: { type: "new",  label: "New" }, art: { shape: "bottle", palette: ["#dfe6df", "#5a8073"] } },
  { id: "p6", title: "Arc Reading Lamp",       category: "Lighting",      price: 245, rating: 4.7, reviews: 96,  art: { shape: "lamp",   palette: ["#e8e3d6", "#b3431a"] } },
  { id: "p7", title: "Heritage Wool Throw",    category: "Home",          price: 119, was: 149, rating: 4.8, reviews: 287, badge: { type: "sale", label: "30% off" }, art: { shape: "shirt",  palette: ["#dcd2bf", "#3a4a3f"] } },
  { id: "p8", title: "Pour-Over Carafe",       category: "Kitchen",       price: 54,  rating: 4.6, reviews: 142, art: { shape: "bottle", palette: ["#e7e0d2", "#2c5d4a"] } },
];

const ARTICLES = [
  { id: "a1", category: "Journal", read: "5 min read",  title: "Designing a quiet kitchen: tools that actually earn their counter space", excerpt: "Our editor pares back to the ten essentials that make daily cooking calmer — and a little more beautiful.",   palette: ["#dfe6df", "#a8c0b3", "#2c5d4a"] },
  { id: "a2", category: "Behind the brand", read: "8 min read", title: "Inside the workshop where our linen overshirts are cut",       excerpt: "A morning with the small studio in Porto that has been making garments to last for three generations.",        palette: ["#f0e3cf", "#d3b994", "#7a4a1f"] },
  { id: "a3", category: "Edit",   read: "3 min read",  title: "The autumn home edit: warm tones, soft light, slow evenings",         excerpt: "Twelve pieces that quietly shift a room from summer's brightness into something far more comforting.",         palette: ["#e7d8c9", "#b58a6c", "#3a2a1f"] },
];

const VALUES = [
  { icon: "truck",  title: "Free shipping over $75", body: "Carbon-neutral delivery across the US." },
  { icon: "rotate", title: "30-day easy returns",    body: "Free returns on full-priced orders." },
  { icon: "leaf",   title: "Responsibly made",       body: "Traceable materials and small-batch partners." },
  { icon: "shield", title: "Lifetime guarantee",     body: "Repair, replace, or recycle — we stand behind it." },
];

/* ---------- Components ---------- */

function Announcement() {
  return (
    <div className="announce" role="region" aria-label="Site announcement">
      Free carbon-neutral shipping on orders over <strong>$75</strong> · Use code <strong>HARVEST</strong> for 15% off new arrivals
    </div>
  );
}

function Header({ cartCount, onOpenCart, onOpenSearch }) {
  const [open, setOpen] = useState(false);
  return (
    <header className="site-header">
      <div className="container header-inner">
        <a href="#top" className="brand" aria-label="Maren and Oak — home">
          <span aria-hidden="true" className="brand-mark">◯</span>&nbsp;Maren &amp; Oak
        </a>

        <nav className={`primary-nav${open ? " open" : ""}`} aria-label="Primary">
          <ul>
            {NAV.map((n, i) => (
              <li key={n.href}>
                <a href={n.href} aria-current={i === 0 ? "page" : undefined} onClick={() => setOpen(false)}>{n.label}</a>
              </li>
            ))}
          </ul>
        </nav>

        <div className="header-actions">
          <button className="icon-btn menu-toggle" type="button" aria-expanded={open} aria-controls="primary-nav" aria-label={open ? "Close menu" : "Open menu"} onClick={() => setOpen(o => !o)}>
            <Icon name={open ? "close" : "menu"} />
          </button>
          <button className="icon-btn" type="button" aria-label="Search" onClick={onOpenSearch}><Icon name="search" /></button>
          <a className="icon-btn" href="#account" aria-label="Account"><Icon name="user" /></a>
          <a className="icon-btn" href="#wishlist" aria-label="Wishlist"><Icon name="heart" /></a>
          <button className="icon-btn" type="button" aria-label={`Cart, ${cartCount} item${cartCount === 1 ? "" : "s"}`} onClick={onOpenCart}>
            <Icon name="bag" />
            {cartCount > 0 && <span className="cart-count" aria-hidden="true">{cartCount}</span>}
          </button>
        </div>
      </div>
    </header>
  );
}

function Hero({ onShop }) {
  return (
    <section className="hero" id="top" aria-labelledby="hero-title">
      <div className="container hero-grid">
        <div className="hero-copy">
          <span className="eyebrow">Autumn 2026 · Now arriving</span>
          <h1 id="hero-title">Quietly considered essentials for the way you actually live.</h1>
          <p>From small workshops to your shelf — apparel, home and kitchen pieces designed to be useful for years, not seasons.</p>
          <div className="hero-cta">
            <button type="button" className="btn btn-primary" onClick={onShop}>Shop the autumn edit</button>
            <a className="btn btn-secondary" href="#editorial">Read the journal</a>
          </div>
          <dl className="hero-meta">
            <div><strong>240+</strong><span>Independent makers</span></div>
            <div><strong>4.9 / 5</strong><span>Average review (12k+)</span></div>
            <div><strong>Carbon-neutral</strong><span>Shipping &amp; returns</span></div>
          </dl>
        </div>
        <div className="hero-art" role="img" aria-label="Illustration of a softly lit reading nook with a lounge chair and arc lamp.">
          <HeroArt />
          <div className="hero-badge"><span className="dot" aria-hidden="true" /> New arrivals every Friday</div>
        </div>
      </div>
    </section>
  );
}

function CategoriesStrip() {
  return (
    <nav className="categories" aria-label="Shop by category">
      <div className="container">
        <ul>
          {CATEGORIES.map(c => (
            <li key={c}><a href={`#cat-${c.toLowerCase().replace(/\W+/g, "-")}`}>{c}</a></li>
          ))}
        </ul>
      </div>
    </nav>
  );
}

function ProductCard({ product, favorite, onToggleFavorite, onAdd }) {
  const priceLabel = product.was
    ? `On sale, was $${product.was}, now $${product.price}`
    : `$${product.price}`;
  return (
    <article className="product-card" aria-labelledby={`pt-${product.id}`}>
      <div className="product-media">
        <ProductArt shape={product.art.shape} palette={product.art.palette} />
        {product.badge && <span className={`badge ${product.badge.type}`}>{product.badge.label}</span>}
        <button
          type="button"
          className="product-fav"
          aria-pressed={favorite}
          aria-label={`${favorite ? "Remove from" : "Add to"} wishlist: ${product.title}`}
          onClick={() => onToggleFavorite(product.id)}
