/* ---------- Layout ---------- */
.container {
  width: 100%;
  max-width: var(--maxw);
  margin: 0 auto;
  padding-inline: var(--gutter);
}

main { display: block; }

section { padding-block: clamp(48px, 7vw, 96px); }

.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: clamp(20px, 3vw, 36px);
}
.section-head .eyebrow {
  display: block;
  text-transform: uppercase;
  letter-spacing: .14em;
  font-size: .75rem;
  color: var(--ink-muted);
  margin-bottom: 8px;
  font-weight: 600;
}
.section-head h2 { margin: 0; }
.section-head p { color: var(--ink-soft); max-width: 56ch; margin: 6px 0 0; }

/* ---------- Announcement bar ---------- */
.announce {
  background: var(--ink);
  color: #f4f1ea;
  font-size: .8125rem;
  text-align: center;
  padding: 8px var(--gutter);
}
.announce strong { color: #fff; }

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(250, 250, 247, 0.92);
  backdrop-filter: saturate(180%) blur(12px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  min-height: 68px;
}
.brand {
  font-family: var(--font-serif);
  font-size: 1.375rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  text-decoration: none;
  color: var(--ink);
}
.brand-mark { display: inline-block; transform: translateY(1px); }

.primary-nav { justify-self: center; }
.primary-nav ul {
  display: flex;
  gap: clamp(14px, 2.4vw, 28px);
  list-style: none;
  margin: 0;
  padding: 0;
}
.primary-nav a {
  text-decoration: none;
  color: var(--ink-soft);
  font-weight: 500;
  font-size: .9375rem;
  padding: 6px 4px;
  border-radius: 4px;
}
.primary-nav a:hover { color: var(--ink); }
.primary-nav a[aria-current="page"] {
  color: var(--ink);
  box-shadow: inset 0 -2px 0 var(--accent);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}
.icon-btn {
  appearance: none;
  background: transparent;
  border: 0;
  color: var(--ink);
  width: 40px;
  height: 40px;
  border-radius: 999px;
  display: inline-grid;
  place-items: center;
  cursor: pointer;
  position: relative;
}
.icon-btn:hover { background: var(--surface-alt); }
.cart-count {
  position: absolute;
  top: 4px;
  right: 4px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: .6875rem;
  font-weight: 700;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  line-height: 1;
}

.menu-toggle { display: none; }

@media (max-width: 820px) {
  .primary-nav { display: none; }
  .menu-toggle { display: inline-grid; }
  .primary-nav.open {
    display: block;
    position: absolute;
    inset: 100% 0 auto 0;
    background: var(--surface);
    border-bottom: 1px solid var(--line);
    padding: 12px var(--gutter) 20px;
  }
  .primary-nav.open ul {
    flex-direction: column;
    gap: 6px;
    align-items: stretch;
  }
  .primary-nav.open a {
    display: block;
    padding: 10px 4px;
    border-bottom: 1px solid var(--line);
  }
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font: inherit;
  font-weight: 600;
  font-size: .9375rem;
  padding: 12px 22px;
  border-radius: 999px;
  border: 1px solid transparent;
  text-decoration: none;
  cursor: pointer;
  min-height: 44px;
  transition: background-color .15s ease, color .15s ease, border-color .15s ease, transform .05s ease;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn-primary:hover { background: var(--accent-hover); }
.btn-secondary {
  background: transparent;
  color: var(--ink);
  border-color: var(--ink);
}
.btn-secondary:hover { background: var(--ink); color: #fff; }
.btn-ghost {
  background: transparent;
  color: var(--ink);
  padding-inline: 4px;
  border-radius: 4px;
  min-height: auto;
}
.btn-ghost:hover { color: var(--accent); }
.btn-ghost::after {
  content: "→";
  transition: transform .2s ease;
}
.btn-ghost:hover::after { transform: translateX(3px); }

/* ---------- Hero ---------- */
.hero {
  padding-block: clamp(40px, 6vw, 72px);
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: clamp(24px, 4vw, 56px);
  align-items: center;
}
.hero-copy .eyebrow {
  text-transform: uppercase;
  letter-spacing: .18em;
  font-size: .75rem;
  font-weight: 600;
  color: var(--accent);
  margin-bottom: 18px;
  display: inline-block;
}
.hero-copy h1 { margin-bottom: 18px; }
.hero-copy p {
  color: var(--ink-soft);
  font-size: 1.0625rem;
  max-width: 52ch;
}
.hero-cta {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 28px;
}
.hero-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 24px 36px;
  margin-top: 40px;
  padding-top: 28px;
  border-top: 1px solid var(--line);
  color: var(--ink-soft);
  font-size: .875rem;
}
.hero-meta strong { display: block; color: var(--ink); font-size: 1.5rem; font-family: var(--font-serif); font-weight: 500; line-height: 1; margin-bottom: 4px; }

.hero-art {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: linear-gradient(135deg, #d8d2c2, #b6b0a0);
  box-shadow: var(--shadow-md);
}
.hero-art svg { position: absolute; inset: 0; width: 100%; height: 100%; }
.hero-badge {
  position: absolute;
  left: 20px;
  bottom: 20px;
  background: var(--surface);
  border-radius: var(--radius);
  padding: 12px 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  box-shadow: var(--shadow-sm);
  font-size: .875rem;
}
.hero-badge .dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--accent);
}

@media (max-width: 820px) {
  .hero-grid { grid-template-columns: 1fr; }
  .hero-art { order: -1; aspect-ratio: 3 / 2; }
}

/* ---------- Categories strip ---------- */
.categories {
  background: var(--surface);
  border-block: 1px solid var(--line);
  padding-block: 28px;
}
.categories ul {
  list-style: none;
  margin: 0; padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  justify-content: center;
}
.categories a {
  display: inline-block;
  padding: 8px 16px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: var(--surface);
  text-decoration: none;
  color: var(--ink);
  font-size: .875rem;
  font-weight: 500;
}
.categories a:hover { border-color: var(--ink); }

/* ---------- Product grid ---------- */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
@media (max-width: 1024px) { .product-grid { grid-template-columns: repeat(3, 1fr); } }
@media (max-width: 760px)  { .product-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 420px)  { .product-grid { grid-template-columns: 1fr; } }

.product-card {
  display: flex;
  flex-direction: column;
  background: transparent;
}
.product-media {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--surface-alt);
  margin-bottom: 14px;
}
.product-media svg { width: 100%; height: 100%; }
.product-card .badge {
  position: absolute;
  top: 10px;
  left: 10px;
  background: var(--ink);
  color: #fff;
  font-size: .6875rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  padding: 4px 8px;
  border-radius: 4px;
}
.product-card .badge.sale { background: var(--sale); }
.product-card .badge.new  { background: var(--accent); }

.product-fav {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 36px;
  height: 36px;
  border-radius: 999px;
  background: rgba(255,255,255,.92);
  border: 1px solid var(--line);
  display: grid;
  place-items: center;
  cursor: pointer;
  color: var(--ink);
}
.product-fav:hover { background: #fff; }
.product-fav[aria-pressed="true"] { color: var(--sale); border-color: var(--sale); }

.product-quick {
  position: absolute;
  inset: auto 10px 10px;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity .18s ease, transform .18s ease;
}
.product-card:hover .product-quick,
.product-card:focus-within .product-quick {
  opacity: 1;
  transform: translateY(0);
}
.product-quick .btn {
  width: 100%;
  background: #fff;
  color: var(--ink);
  border: 1px solid var(--ink);
  padding: 10px 16px;
  min-height: 40px;
}
.product-quick .btn:hover { background: var(--ink); color: #fff; }

.product-meta {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
}
.product-title {
  font-size: .9375rem;
  font-weight: 500;
  margin: 0 0 2px;
  color: var(--ink);
  text-decoration: none;
}
.product-title:hover { color: var(--accent); }
.product-cat {
  font-size: .75rem;
  color: var(--ink-muted);
  text-transform: uppercase;
  letter-spacing: .1em;
  margin: 0 0 6px;
}
.product-price {
  font-weight: 600;
  font-size: .9375rem;
  white-space: nowrap;
}
.product-price .was {
  color: var(--ink-muted);
  text-decoration: line-through;
  font-weight: 400;
  margin-right: 6px;
}
.product-rating {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
  font-size: .8125rem;
  color: var(--ink-muted);
}
.stars { color: #c8911a; letter-spacing: 1px; }

/* ---------- Deals ---------- */
.deals {
  background: var(--surface);
}
.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 20px;
}
@media (max-width: 900px) { .deals-grid { grid-template-columns: 1fr 1fr; } .deals-card.lg { grid-column: 1 / -1; } }
@media (max-width: 560px) { .deals-grid { grid-template-columns: 1fr; } }

.deals-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  padding: 32px;
  min-height: 260px;
  display: flex;
  flex-direction: column;
  justify-content: end;
  color: var(--ink);
  isolation: isolate;
  background-color: var(--surface-alt);
}
.deals-card.dark { background-color: #1f4536; }
.deals-card .bg {
  position: absolute; inset: 0; z-index: -1;
}
.deals-card .bg svg { width: 100%; height: 100%; }
.deals-card .tag {
  position: absolute;
  top: 20px;
  left: 20px;
  background: var(--ink);
  color: #fff;
  padding: 6px 12px;
  border-radius: 999px;
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
}
.deals-card h3 {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 2.4vw, 2rem);
  font-weight: 500;
  letter-spacing: -0.01em;
  margin: 0 0 8px;
}
.deals-card p { color: var(--ink-soft); margin-bottom: 18px; max-width: 36ch; }
.deals-card.lg { min-height: 360px; }
.deals-card.dark { color: #f4f1ea; }
.deals-card.dark p { color: #d6d2c5; }
.deals-card.dark .tag { background: #fff; color: var(--ink); }
.deals-card.dark .btn-secondary { color: #fff; border-color: #fff; }
.deals-card.dark .btn-secondary:hover { background: #fff; color: var(--ink); }

.countdown {
  display: flex;
  gap: 8px;
  margin-bottom: 18px;
  font-variant-numeric: tabular-nums;
}
.countdown div {
  background: rgba(255,255,255,.85);
  color: var(--ink);
  border-radius: 8px;
  padding: 8px 10px;
  min-width: 56px;
  text-align: center;
}
.countdown strong { display: block; font-size: 1.25rem; font-family: var(--font-serif); font-weight: 500; line-height: 1; }
.countdown span { font-size: .6875rem; text-transform: uppercase; letter-spacing: .08em; color: var(--ink-muted); }

/* ---------- Editorial ---------- */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}
@media (max-width: 900px) { .editorial-grid { grid-template-columns: 1fr 1fr; } }
@media (max-width: 600px) { .editorial-grid { grid-template-columns: 1fr; } }

