.article .meta {
  font-size: .75rem;
  color: var(--ink-muted);
  text-transform: uppercase;
  letter-spacing: .12em;
  margin-bottom: 8px;
}
.article h3 {
  font-family: var(--font-serif);
  font-size: 1.375rem;
  font-weight: 500;
  letter-spacing: -0.01em;
  line-height: 1.25;
  margin: 0 0 8px;
}
.article h3 a { text-decoration: none; }
.article h3 a:hover { color: var(--accent); }
.article p { color: var(--ink-soft); margin-bottom: 12px; }

