* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.55;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img, svg { display: block; max-width: 100%; }
img { height: auto; }

a { color: inherit; }

h1, h2, h3, h4 {
  font-family: var(--font-serif);
  font-weight: 500;
  letter-spacing: -0.01em;
  margin: 0 0 .4em;
  line-height: 1.15;
}

h1 { font-size: clamp(2.25rem, 5vw, 4rem); }
h2 { font-size: clamp(1.625rem, 3vw, 2.25rem); }
h3 { font-size: 1.125rem; font-family: var(--font-sans); font-weight: 600; letter-spacing: 0; }

p { margin: 0 0 1em; }

/* ---------- Focus ---------- */
:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 3px;
}

.skip-link {
  position: absolute;
  left: 8px;
  top: -40px;
  background: var(--ink);
  color: #fff;
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  text-decoration: none;
  z-index: 1000;
}
.skip-link:focus { top: 8px; }

/* ---------- Layout ---------- */
.container {
  width: 100%;
  max-width: var(--maxw);
  margin: 0 auto;
  padding-inline: var(--gutter);
}

main { display: block; }

section { padding-block: clamp(48px, 7vw, 96px); }

.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: clamp(20px, 3vw, 36px);
}
.section-head .eyebrow {
  display: block;
  text-transform: uppercase;
  letter-spacing: .14em;
  font-size: .75rem;
  color: var(--ink-muted);
  margin-bottom: 8px;
  font-weight: 600;
}
.section-head h2 { margin: 0; }
.section-head p { color: var(--ink-soft); max-width: 56ch; margin: 6px 0 0; }

/* ---------- Announcement bar ---------- */
.announce {
  background: var(--ink);
  color: #f4f1ea;
  font-size: .8125rem;
  text-align: center;
  padding: 8px var(--gutter);
}
.announce strong { color: #fff; }

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(250, 250, 247, 0.92);
  backdrop-filter: saturate(180%) blur(12px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  min-height: 68px;
}
.brand {
  font-family: var(--font-serif);
  font-size: 1.375rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  text-decoration: none;
  color: var(--ink);
}
.brand-mark { display: inline-block; transform: translateY(1px); }

.primary-nav { justify-self: center; }
.primary-nav ul {
  display: flex;
  gap: clamp(14px, 2.4vw, 28px);
  list-style: none;
  margin: 0;
  padding: 0;
}
.primary-nav a {
  text-decoration: none;
  color: var(--ink-soft);
  font-weight: 500;
  font-size: .9375rem;
  padding: 6px 4px;
  border-radius: 4px;
}
.primary-nav a:hover { color: var(--ink); }
.primary-nav a[aria-current="page"] {
  color: var(--ink);
  box-shadow: inset 0 -2px 0 var(--accent);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}
.icon-btn {
