  font-size: .6875rem;
  font-weight: 700;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  line-height: 1;
}

.menu-toggle { display: none; }

@media (max-width: 820px) {
