  .menu-toggle { display: inline-grid; }
  .primary-nav.open {
    display: block;
    position: absolute;
    inset: 100% 0 auto 0;
    background: var(--surface);
    border-bottom: 1px solid var(--line);
    padding: 12px var(--gutter) 20px;
  }
  .primary-nav.open ul {
    flex-direction: column;
    gap: 6px;
    align-items: stretch;
  }
  .primary-nav.open a {
    display: block;
    padding: 10px 4px;
    border-bottom: 1px solid var(--line);
  }
}

/* ---------- Buttons ---------- */
.btn {
