  color: var(--ink-soft);
  font-size: 1.0625rem;
  max-width: 52ch;
}
.hero-cta {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 28px;
}
.hero-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 24px 36px;
  margin-top: 40px;
  padding-top: 28px;
  border-top: 1px solid var(--line);
  color: var(--ink-soft);
  font-size: .875rem;
}
.hero-meta dt { font-size: .875rem; color: var(--ink-soft); order: 2; }
.hero-meta dd { display: block; color: var(--ink); font-size: 1.5rem; font-family: var(--font-serif); font-weight: 500; line-height: 1; margin: 0 0 4px; order: 1; }
.hero-meta > div { display: flex; flex-direction: column; }

.hero-art {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: linear-gradient(135deg, #d8d2c2, #b6b0a0);
