}
.product-quick .btn:hover { background: var(--ink); color: #fff; }

.product-meta {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
}
.product-title {
  font-size: .9375rem;
  font-weight: 500;
  margin: 0 0 2px;
  color: var(--ink);
  text-decoration: none;
}
.product-title:hover { color: var(--accent); }
.product-cat {
  font-size: .75rem;
