  text-transform: uppercase;
  letter-spacing: .1em;
  margin: 0 0 6px;
}
.product-price {
  font-weight: 600;
  font-size: .9375rem;
  white-space: nowrap;
}
.product-price .was {
  color: var(--ink-muted);
