/* ---------- Decorative SVG illustrations (no external images) ---------- */

function HeroArt() {
  return (
    <svg viewBox="0 0 600 750" preserveAspectRatio="xMidYMid slice" aria-hidden="true" focusable="false">
      <defs>
        <linearGradient id="hg" x1="0" y1="0" x2="1" y2="1">
