      <rect width="600" height="750" fill="url(#hg)" />
      <rect width="600" height="750" fill="url(#hr)" />
      {/* Stylised lamp + chair silhouette */}
      <g fill="#2c5d4a" opacity=".9">
        <rect x="380" y="520" width="160" height="14" rx="3" />
        <rect x="445" y="320" width="6" height="200" />
        <ellipse cx="448" cy="320" rx="55" ry="22" />
        <path d="M393 320 Q448 230 503 320 Z" />
