function useCountdown(targetMs) {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  const diff = Math.max(0, targetMs - now);
  const s = Math.floor(diff / 1000);
  return {
    days: Math.floor(s / 86400),
    hours: Math.floor((s % 86400) / 3600),
    minutes: Math.floor((s % 3600) / 60),
    seconds: s % 60,
  };
}

function Countdown() {
  const target = useMemo(() => Date.now() + 1000 * 60 * 60 * 32 + 1000 * 47, []);
  const { days, hours, minutes, seconds } = useCountdown(target);
  const fmt = n => String(n).padStart(2, "0");
  const label = `${days} day${days === 1 ? "" : "s"}, ${hours} hours, ${minutes} minutes and ${seconds} seconds remaining`;
  return (
    <div className="countdown" role="timer" aria-live="off" aria-label={`Sale ends in ${label}`}>
      <div><strong>{fmt(days)}</strong><span>Days</span></div>
      <div><strong>{fmt(hours)}</strong><span>Hrs</span></div>
      <div><strong>{fmt(minutes)}</strong><span>Min</span></div>
      <div><strong>{fmt(seconds)}</strong><span>Sec</span></div>
    </div>
  );
}

